use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::os::unix::fs::MetadataExt;
use std::os::unix::io::{AsRawFd, FromRawFd};
use std::collections::HashMap;
use sha2::{Sha256, Digest};

const SESSION_DIR: &str = "/var/lib/app/sessions";
const MAX_SESSION_SIZE: u64 = 8192;

// O_NOFOLLOW prevents symlink following at open time
const O_RDONLY: i32 = 0;
const O_NOFOLLOW: i32 = 0o400000;
const O_WRONLY: i32 = 1;
const O_CREAT: i32 = 0o100;
const O_TRUNC: i32 = 0o1000;
const O_EXCL: i32 = 0o200;

extern "C" {
    fn open(path: *const u8, flags: i32, mode: u32) -> i32;
    fn fstat(fd: i32, buf: *mut libc_stat) -> i32;
    fn close(fd: i32) -> i32;
}

#[repr(C)]
struct libc_stat {
    st_dev: u64,
    st_ino: u64,
    st_nlink: u64,
    st_mode: u32,
    st_uid: u32,
    st_gid: u32,
    _pad0: u32,
    st_rdev: u64,
    st_size: i64,
    st_blksize: i64,
    st_blocks: i64,
    st_atime: i64,
    st_atime_nsec: i64,
    st_mtime: i64,
    st_mtime_nsec: i64,
    st_ctime: i64,
    st_ctime_nsec: i64,
    _reserved: [i64; 3],
}

pub struct SessionManager {
    base_dir: PathBuf,
    expected_uid: u32,
}

impl SessionManager {
    pub fn new(base_dir: &str, uid: u32) -> Self {
        SessionManager {
            base_dir: PathBuf::from(base_dir),
            expected_uid: uid,
        }
    }

    /// Validates that a session ID contains only safe characters
    fn validate_session_id(session_id: &str) -> Result<(), &'static str> {
        if session_id.len() < 16 || session_id.len() > 64 {
            return Err("Invalid session ID length");
        }
        if !session_id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            return Err("Invalid session ID characters");
        }
        Ok(())
    }

    /// Constructs the canonical path for a session file
    fn session_path(&self, session_id: &str) -> Result<PathBuf, &'static str> {
        let path = self.base_dir.join(session_id);
        let canonical_base = self.base_dir.canonicalize()
            .map_err(|_| "Cannot resolve base directory")?;
        let parent = path.parent().ok_or("Invalid path")?;
        let canonical_parent = parent.canonicalize()
            .map_err(|_| "Cannot resolve parent directory")?;
        if canonical_parent != canonical_base {
            return Err("Path traversal detected");
        }
        Ok(path)
    }

    /// Opens file with O_NOFOLLOW and verifies ownership on the SAME fd
    /// This eliminates TOCTOU by using fstat on the opened file descriptor
    fn open_and_verify(&self, path: &Path) -> Result<fs::File, &'static str> {
        let path_bytes = path.to_str().ok_or("Invalid path encoding")?;
        let c_path = format!("{}\0", path_bytes);

        let fd = unsafe {
            open(c_path.as_ptr(), O_RDONLY | O_NOFOLLOW, 0)
        };

        if fd < 0 {
            return Err("Cannot open session file (may be symlink)");
        }

        // fstat on the OPEN file descriptor - no TOCTOU possible
        let mut stat_buf: libc_stat = unsafe { std::mem::zeroed() };
        let stat_result = unsafe { fstat(fd, &mut stat_buf) };

        if stat_result != 0 {
            unsafe { close(fd); }
            return Err("Cannot stat session file");
        }

        // Verify ownership on the same fd we opened
        if stat_buf.st_uid != self.expected_uid {
            unsafe { close(fd); }
            return Err("Session file ownership mismatch");
        }

        // Verify it's a regular file (mode check)
        if (stat_buf.st_mode & 0o170000) != 0o100000 {
            unsafe { close(fd); }
            return Err("Not a regular file");
        }

        // Check size limit
        if stat_buf.st_size < 0 || stat_buf.st_size as u64 > MAX_SESSION_SIZE {
            unsafe { close(fd); }
            return Err("Session file too large");
        }

        // Convert fd to a safe File handle - we read from the SAME fd we verified
        let file = unsafe { fs::File::from_raw_fd(fd) };
        Ok(file)
    }

    /// Loads session data from disk - open+fstat atomic verification
    pub fn load_session(&self, session_id: &str) -> Result<HashMap<String, String>, &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;

        // Atomically open and verify - no TOCTOU window
        let mut file = self.open_and_verify(&path)?;

        let mut contents = String::new();
        file.read_to_string(&mut contents)
            .map_err(|_| "Cannot read session file")?;

        // Parse session data (simple key=value format)
        let mut session_data = HashMap::new();
        for line in contents.lines() {
            if let Some((key, value)) = line.split_once('=') {
                let key = key.trim().to_string();
                let value = value.trim().to_string();
                if key.len() <= 128 && value.len() <= 1024 {
                    session_data.insert(key, value);
                }
            }
        }

        Ok(session_data)
    }

    /// Saves session data to disk securely
    pub fn save_session(&self, session_id: &str, data: &HashMap<String, String>) -> Result<(), &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;

        let mut content = String::new();
        for (key, value) in data {
            if key.contains('=') || key.contains('\n') || value.contains('\n') {
                return Err("Invalid characters in session data");
            }
            content.push_str(&format!("{}={}\n", key, value));
        }

        if content.len() > MAX_SESSION_SIZE as usize {
            return Err("Session data too large");
        }

        // FIX (unrelated CWE-59): open the write target with O_NOFOLLOW so a
        // planted symlink cannot cause the write to follow to an arbitrary
        // file. We remove any existing file first (verified via open_and_verify
        // when present) and create exclusively with O_CREAT|O_EXCL|O_WRONLY
        // |O_NOFOLLOW, then write through the safe fd.
        let path_str = path.to_str().ok_or("Invalid path encoding")?;
        let c_path = format!("{}\0", path_str);

        // Remove any existing regular file we own so O_EXCL can succeed.
        if path.symlink_metadata().is_ok() {
            // Only unlink after verifying it is a regular file we own; if the
            // verification fails (e.g. it's a symlink), open_and_verify errors
            // out and we refuse to overwrite it.
            let _verified = self.open_and_verify(&path)?;
            fs::remove_file(&path).map_err(|_| "Cannot replace session file")?;
        }

        let fd = unsafe {
            open(
                c_path.as_ptr(),
                O_WRONLY | O_CREAT | O_EXCL | O_TRUNC | O_NOFOLLOW,
                0o600,
            )
        };
        if fd < 0 {
            return Err("Cannot create session file safely");
        }
        let mut file = unsafe { fs::File::from_raw_fd(fd) };
        file.write_all(content.as_bytes())
            .map_err(|_| "Cannot write session file")?;

        Ok(())
    }

    /// Deletes a session - uses open_and_verify to confirm before unlinking
    pub fn delete_session(&self, session_id: &str) -> Result<(), &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;
        // Verify we can open it safely first
        let _file = self.open_and_verify(&path)?;
        // File is verified as ours, now unlink
        fs::remove_file(&path).map_err(|_| "Cannot delete session")?;
        Ok(())
    }

    /// Generates a hash of session content for integrity checking
    pub fn session_fingerprint(&self, session_id: &str) -> Result<String, &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;

        let mut file = self.open_and_verify(&path)?;
        let mut contents = Vec::new();
        file.read_to_end(&mut contents)
            .map_err(|_| "Cannot read session for fingerprint")?;

        let mut hasher = Sha256::new();
        hasher.update(&contents);
        Ok(format!("{:x}", hasher.finalize()))
    }
}

/// HTTP handler that processes session-based requests
pub fn handle_request(uid: u32, session_id: &str, action: &str) -> Result<String, &'static str> {
    let manager = SessionManager::new(SESSION_DIR, uid);

    match action {
        "load" => {
            let data = manager.load_session(session_id)?;
            Ok(format!("Session loaded with {} entries", data.len()))
        }
        "fingerprint" => {
            let fp = manager.session_fingerprint(session_id)?;
            Ok(format!("Fingerprint: {}", fp))
        }
        "delete" => {
            manager.delete_session(session_id)?;
            Ok("Session deleted".to_string())
        }
        _ => Err("Unknown action")
    }
}
